import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 52 Mud is mud","description":"学习 名词化与动作还原，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 52 Mud is mud","description":"学习 名词化与动作还原，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 名词化与动作还原，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 51 Predicting the future","link":"/life/english/new-concept/book-3/unit-03/lesson-051"},"next":{"text":"第三册：培养技能 · Lesson 53 In the public interest","link":"/life/english/new-concept/book-3/unit-03/lesson-053"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 51 Predicting the future","link":"/life/english/new-concept/book-3/unit-03/lesson-051"},"next":{"text":"第三册：培养技能 · Lesson 53 In the public interest","link":"/life/english/new-concept/book-3/unit-03/lesson-053"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-052.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-052.md"}'),o={name:"life/english/new-concept/book-3/unit-03/lesson-052.md"};function l(r,e,s,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第三册-培养技能-·-lesson-52-mud-is-mud" tabindex="-1">第三册：培养技能 · Lesson 52 Mud is mud <a class="header-anchor" href="#第三册-培养技能-·-lesson-52-mud-is-mud" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 52 Mud is mud&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕宣传修饰与实际品质之间的差异，训练以具体词汇替代夸大包装。语言可以改变印象，却不能自动改变事实。学习名词化与动词表达如何影响句子清晰度，能够把抽象陈述还原成谁做了什么，并保留评价所依据的可观察指标。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>substance</td><td>/ˈsʌbstəns/</td><td>n.</td><td>实质或物质</td><td>the actual substance</td></tr><tr><td>label</td><td>/ˈleɪbl/</td><td>n.</td><td>标签</td><td>a misleading label</td></tr><tr><td>description</td><td>/dɪˈskrɪpʃən/</td><td>n.</td><td>描述</td><td>an accurate description</td></tr><tr><td>evaluation</td><td>/ɪˌvæljuˈeɪʃən/</td><td>n.</td><td>评估</td><td>a product evaluation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in plain language — 用清楚朴素的语言</li><li>live up to — 达到宣传或期待</li></ul><h2 id="语法讲解-名词化与动作还原" tabindex="-1">语法讲解：名词化与动作还原 <a class="header-anchor" href="#语法讲解-名词化与动作还原" aria-label="Permalink to &quot;语法讲解：名词化与动作还原&quot;">​</a></h2><p>名词化把动作或性质表达为名词，如 examine 变 examination，常用于正式报告。它能压缩信息，但连续使用抽象名词可能隐藏行动者、时间和责任。把 The evaluation of the product was carried out 改为 The team evaluated the product，可恢复主体与谓语。名词化本身并非错误，在需要概括过程或衔接前文时很有用；关键是读者是否知道谁执行、依据什么及结果如何。改写时须保留原本的时态和限定范围，不能只为简洁而新增行动者。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The seller called the mixture a premium finish, but the label did not explain its ingredients.</p></blockquote><p>卖家称这种混合物为高级涂层，但标签没有解释其成分。</p><p>called 加宾语和名词补语报告命名；but 后用具体缺失信息检验宣传，而非仅凭名称判断品质。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>把抽象被动改主动时不能凭空加入专家等未提供的行动者；未知主体可保留被动或明确写“报告未说明”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>分别朗读 carried out an evaluation 和 evaluated，比较信息密度；把示范中 no figures 重读，突出判断依据而非宣传形容词。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The brochure calls the fabric revolutionary. It gives no figures for strength or durability. We should test a sample before accepting the description.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句评价一段虚构商品宣传，区分名称和证据。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先准确报告宣传，再指出证据缺口，最后提出验证步骤。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>将 The team carried out an inspection of the box 改得更直接。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The team inspected the box.</p><p><strong>解析：</strong> 用动词恢复主要动作并保留已知主语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句能仅凭 premium 判断质量吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 这是卖家的命名，成分信息仍缺失。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>evaluation 的动词形式是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> evaluate</p><p><strong>解析：</strong> 名词化对应动作动词 evaluate。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：名词化与动作还原。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-051">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-053">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",l]]);export{p as __pageData,b as default};
